// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _test(address _target, uint256 _value) internal {
        vm.assume(_target != address(0) && _value > 0);
        vm.assume(_target != address(this));
        uint balBefore = _target.balance;
        try c.sendMoney(_target, _value) {} catch { return; }
        assertTrue(_target.balance == balBefore + _value);
    }

    function testFuzz_test(address _target, uint256 _value) public {
        _test(_target, _value);
    }

    receive() external payable {}
}
